// ALLY 13 – Formular lesen (Stefan 17.10.2026: alles, was im Chat geht, auch über die Kacheln). Herkunft prüfen wie bei ALLY 8, Sitzung aus dem Cookie,
// Felder je Aktion aufbereiten. Zeiten aus der Oberfläche sind Berliner Zeit und gehen als ISO mit Zeitzone weiter.
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben). n8n ist nur über traefik erreichbar,
// traefik leitet nur eingerichtete Adressen weiter. So gelten die bisherige n8n-Adresse und die eigene Adresse der Oberfläche ohne feste Werte (17.10.2026).
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {}, b = $json.body || {};
const herkunft = String(h.origin || ''), verweis = String(h.referer || '');
// Verweis nur von der Seite selbst: nach dem Pfad folgt Ende, '/', '?' oder '#', nicht z. B. '-boese' (Stefan 17.10.2026)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(v ?? '').trim();
const zahl = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
const AKTIONEN = ['beitrag', 'freigeben', 'verwerfen', 'posten', 'stornieren', 'loeschen', 'klaerung', 'entwurf', 'ablehnen', 'neue_mail',
  'termin_neu', 'termin_aendern', 'termin_loeschen', 'systemmails', 'fragen', 'kalender_einstellen'];
const aktion = herkunftOk && AKTIONEN.includes(s(b.aktion)) ? s(b.aktion) : 'ungueltig';
// Berliner Zeit aus einem Feld "datetime-local" (JJJJ-MM-TTTHH:MM) oder "date" (JJJJ-MM-TT); leer bleibt leer, Unsinn wird "x" (lehnt die Datenbank ab)
const zeit = v => { const t = s(v); if (!t) return ''; const d = DateTime.fromISO(t, { zone: 'Europe/Berlin' }); return d.isValid ? d.toISO({ suppressMilliseconds: true }) : 'x'; };
const KAN = ['instagram_post', 'instagram_story', 'linkedin', 'whatsapp'];
let d = {};
if (aktion === 'beitrag') {
  const gewaehlt = KAN.filter(k => b['kanal__' + k]);
  const bisher = s(b.bisher).split(',').filter(k => KAN.includes(k));
  d = { thema: zahl(b.thema), freies_thema: s(b.freies_thema).slice(0, 600), hinweise: s(b.hinweise).slice(0, 3100), story_modus: s(b.story_modus),
    kanaele: gewaehlt.filter(k => !bisher.includes(k)), entfernen: bisher.filter(k => !gewaehlt.includes(k)).join(',') };
} else if (['freigeben', 'verwerfen', 'loeschen'].includes(aktion)) d = { thema: zahl(b.thema) };
else if (aktion === 'posten') d = { thema: zahl(b.thema), kanal: s(b.kanal), format: s(b.format), zeitpunkt: zeit(b.zeitpunkt) };
else if (aktion === 'stornieren') d = { post: zahl(b.post) };
else if (aktion === 'klaerung') d = { id: zahl(b.id), antwort: s(b.antwort).slice(0, 2100) };
else if (aktion === 'entwurf' || aktion === 'ablehnen') d = { id: zahl(b.id), anweisung: s(b.anweisung).slice(0, 3100) };
else if (aktion === 'neue_mail') d = { postfach: s(b.postfach), an: s(b.an), an_name: s(b.an_name), betreff: s(b.betreff).slice(0, 210), anweisung: s(b.anweisung).slice(0, 3100) };
else if (aktion.startsWith('termin_')) {
  const ganz = s(b.ganztaegig) === '1';
  // Ganztägig: Ende ist der letzte Tag; Google erwartet den Tag danach (exklusiv)
  const tag = v => { const t = s(v).slice(0, 10); const x = DateTime.fromISO(t, { zone: 'Europe/Berlin' }); return x.isValid ? x : null; };
  let start = zeit(b.start), ende = zeit(b.ende);
  if (ganz) { const a = tag(b.start_tag || b.start), e = tag(b.ende_tag || b.ende || b.start_tag || b.start); start = a ? a.toISODate() : (s(b.start) ? 'x' : ''); ende = e ? e.plus({ days: 1 }).toISODate() : (start && start !== 'x' ? DateTime.fromISO(start).plus({ days: 1 }).toISODate() : ''); }
  d = { termin: s(b.termin).slice(0, 210), titel: s(b.titel).slice(0, 210), start, ende, ganztaegig: ganz ? '1' : '', ort: s(b.ort).slice(0, 210), beschreibung: s(b.beschreibung_behalten) === '1' ? '' : s(b.beschreibung).slice(0, 2100) };
}
else if (aktion === 'systemmails') d = { tage: zahl(b.tage) };
else if (aktion === 'fragen') d = { text: s(b.text).slice(0, 2100) };
else if (aktion === 'kalender_einstellen') d = { kalender_id: s(b.kalender_id).slice(0, 210) };
// Rücksprung: dieselbe Maske (beim Marketing das gewählte Thema), Position wie bei ALLY 8
const zurueck = { thema: zahl(b.zurueck_thema) };
return [{ json: { token, aktion, daten: JSON.stringify(d), zurueck } }];

