// ALLY 13 – Antwort bauen: zurück auf die Maske, von der die Aktion kam; Sitzung wie bei ALLY 8 behandeln
const SEITE = '/webhook/web';
const F = $('Formular lesen').first().json;
const r = $('Prüfen').first().json.r || {};
const ZQ = $('Aktion').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
const MASKE = { beitrag: 'beitrag', freigeben: 'beitrag', verwerfen: 'beitrag', posten: 'beitrag', stornieren: 'beitrag', loeschen: 'beitrag', klaerung: 'belege_verbuchen',
  entwurf: 'mails', ablehnen: 'mails', neue_mail: 'mails', termin_neu: 'kalender', termin_aendern: 'kalender', termin_loeschen: 'kalender', systemmails: 'systemmails', fragen: 'fragen' };
let ziel, cookie = '';
if (F.aktion === 'ungueltig' || r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else {
  // Gelöschtes Thema: zurück zur Übersicht; sonst beim gewählten Thema bleiben
  const thema = F.aktion === 'loeschen' && r.ok ? '' : (F.zurueck && F.zurueck.thema) || '';
  ziel = F.aktion === 'kalender_einstellen' ? stelle(SEITE + '?ansicht=einstellungen&bereich=profil') : stelle(SEITE + '?ansicht=' + (MASKE[F.aktion] || 'beitrag') + (thema && MASKE[F.aktion] === 'beitrag' ? '&thema=' + thema : ''));
  if (F.token) cookie = keks(F.token, 2592000);
}
return [{ json: { ziel, set_cookie: cookie } }];

// Themenordner über SPEICHER 1 löschen (mit allen Unterordnern)
const r = $('Prüfen').first().json.r || {};
return [{ json: { aktion: 'loeschen', bereich: 'ally', pfad: String(r.ordner || '') } }];

// Ergebnis Löschen: erst wenn die Dateien weg sind (oder es keine gab), löscht arbeit_web_abschluss das Thema in der Datenbank
const r = $('Prüfen').first().json.r || {};
const titel = '„' + (r.titel || 'Thema') + '“';
if (!r.ordner) return [{ json: { ok: true, text: titel + ' ist gelöscht.' } }];
const j = $input.first().json || {};
if (j.ok === true) return [{ json: { ok: true, text: titel + ' ist gelöscht, samt ' + (j.vorhanden === false ? 'Eintrag (Dateien waren schon weg).' : 'Dateien.') } }];
return [{ json: { ok: false, text: titel + ' ist nicht gelöscht. Die Dateien ließen sich nicht entfernen: ' + (j.fehler || (j.error && (j.error.message || j.error)) || 'unbekannter Fehler') } }];

// Ergebnis ALLY 6 (Entwurf liegt im Entwürfe-Ordner des Postfachs, nichts wird verschickt)
const j = $input.first().json || {};
const fehlerText = e => String((e && (e.message || e.description)) || e || '').replace(/\s*\[line \d+\]\s*$/, '').trim();
if (j.error || j.status !== 'Entwurf angelegt') return [{ json: { ok: false, text: 'Kein Entwurf angelegt: ' + (fehlerText(j.error) || 'unbekannter Fehler.') } }];
return [{ json: { ok: true, text: 'Entwurf liegt im Ordner „' + (j.ordner || 'Entwürfe') + '“ von ' + j.postfach + '. Er wird nicht verschickt.',
  ergebnis: { art: 'mailentwurf', postfach: String(j.postfach || ''), an: String(j.an || ''), betreff: String(j.betreff || ''), text: String(j.entwurf || '').slice(0, 6000) } } }];

// Ergebnis Kalender (anlegen, ändern, löschen)
const r = $('Prüfen').first().json.r || {};
const j = $input.first().json || {};
const fehlerText = e => String((e && (e.message || e.description)) || e || '').replace(/\s*\[line \d+\]\s*$/, '').trim();
const was = { termin_neu: 'angelegt', termin_aendern: 'geändert', termin_loeschen: 'gelöscht' }[r.art] || 'gespeichert';
if (j.error) return [{ json: { ok: false, text: 'Termin nicht ' + was + ': ' + (fehlerText(j.error) || 'unbekannter Fehler.') } }];
return [{ json: { ok: true, text: r.art === 'termin_loeschen' ? 'Termin gelöscht.' : 'Termin „' + (j.summary || r.titel) + '“ ' + was + '.' } }];

// Ergebnis ALLY 2: Zusammenfassung der System-Mails, steht danach auf der Seite
const r = $('Prüfen').first().json.r || {};
const j = $input.first().json || {};
const fehlerText = e => String((e && (e.message || e.description)) || e || '').replace(/\s*\[line \d+\]\s*$/, '').trim();
if (j.error) return [{ json: { ok: false, text: 'Keine Zusammenfassung: ' + (fehlerText(j.error) || 'unbekannter Fehler.') } }];
let c = j.content; if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { } }
const text = (Array.isArray(c) ? c : [c]).map(x => typeof x === 'string' ? x : (x && x.type === 'text' ? x.text : '')).filter(Boolean).join('\n\n').trim();
if (!text) return [{ json: { ok: false, text: 'Keine Zusammenfassung erhalten.' } }];
return [{ json: { ok: true, text: 'Zusammenfassung der letzten ' + r.tage + ' Tage steht unten.', ergebnis: { art: 'systemmails', tage: r.tage, text: text.slice(0, 8000) } } }];

// Ergebnis Ally fragen: Frage steht im Chat, ALLY 1 antwortet dort
const s = $('Frage in den Chat (SYS 4)').first().json || {};
const a = $input.first().json || {};
// Produktname aus der Einstellung produkt_name; ohne Namen neutrale Texte (Stefan 18.10.2026)
const P = String($('Prüfen').first().json.produkt_name || '').trim();
if (a.error) return [{ json: { ok: false, text: 'Die Frage ist nicht ' + (P ? 'bei ' + P + ' ' : '') + 'angekommen. Bitte im Chat stellen.' } }];
return [{ json: { ok: true, text: (P ? 'Deine Frage ist bei ' + P + '.' : 'Deine Frage ist angekommen.') + ' Die Antwort kommt in etwa einer halben Minute in den Chat.' + (s.error ? ' (Die Frage selbst konnte nicht in den Chat geschrieben werden.)' : '') } }];

// ALLY 13 – Download lesen: Sitzung aus dem Cookie, Thema und optional eine Datei (relativer Pfad im Themenordner)
const h = $json.headers || {}, q = $json.query || {};
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const thema = /^[0-9]{1,9}$/.test(String(q.thema || '')) ? String(q.thema) : '';
const d = String(q.datei || '').trim();
const datei = d.length <= 300 && !d.startsWith('/') && !d.includes('\\') && !/[\u0000-\u001f\u007f*?{}]/.test(d) && d.split('/').every(t => t && t !== '.' && t !== '..') ? d : '';
return [{ json: { token, thema, datei, datei_falsch: d !== '' && datei === '' } }];

// Eine Datei aus dem Themenordner holen
const r = $('Download prüfen').first().json.r || {};
return [{ json: { aktion: 'holen', bereich: 'ally', pfad: r.ordner + '/' + $('Download lesen').first().json.datei } }];

// Download nicht möglich: zurück zur Maske Marketing-Beiträge (Meldung steht in der Sitzung)
const SEITE = '/webhook/web';
const A = $('Download lesen').first().json;
const r = $('Download prüfen').first().json.r || {};
if (r.angemeldet === false) return [{ json: { ziel: SEITE + '?m=abgelaufen', set_cookie: 'ally_sitzung=; Path=' + SEITE + '; Max-Age=0; HttpOnly; Secure; SameSite=None' } }];
return [{ json: { ziel: SEITE + '?ansicht=beitrag' + (A.thema ? '&thema=' + A.thema : ''), set_cookie: '' } }];

// Themenordner auflisten (erste Ebene)
const o = $('Download prüfen').isExecuted ? ($('Download prüfen').first().json.r || {}).ordner : (($json.auftrag || {}).ordner);
return [{ json: { aktion: 'liste', bereich: 'ally', pfad: String(o || '') } }];

// Unterordner des Themenordners auflisten (zweite Ebene). Ohne Unterordner noch einmal die erste Ebene, damit der Ablauf weiterläuft.
const w = $input.first().json || {};
const unter = (w.eintraege || []).filter(e => e.ordner && !String(e.name).startsWith('.'));
return (unter.length ? unter : [null]).map(e => ({ json: { aktion: 'liste', bereich: 'ally', pfad: e ? w.pfad + '/' + e.name : w.pfad } }));

// Alle Dateien des Themenordners (erste und zweite Ebene) mit Pfad relativ zum Themenordner
const w = $('Ordner lesen (SPEICHER 1)').first().json || {};
const basis = String(w.pfad || '');
const liste = [];
if (w.ok === true) for (const e of w.eintraege || []) if (!e.ordner && !String(e.name).startsWith('.')) liste.push({ pfad: e.name, ordner: '', name: e.name, bytes: e.bytes });
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.ok !== true || j.pfad === basis) continue;
  const unter = String(j.pfad).slice(basis.length + 1);
  for (const e of j.eintraege || []) if (!e.ordner && !String(e.name).startsWith('.')) liste.push({ pfad: unter + '/' + e.name, ordner: unter, name: e.name, bytes: e.bytes });
}
liste.sort((a, b) => (a.ordner || '').localeCompare(b.ordner || '') || a.name.localeCompare(b.name, 'de', { numeric: true }));
const fehler = w.ok === true ? '' : (w.fehler || 'Der Themenordner konnte nicht gelesen werden.');
if (fehler || !liste.length) return [{ json: { leer: true, fehler: fehler || 'Im Themenordner liegen keine Dateien.' } }];
const r = $('Download prüfen').first().json.r || {};
return liste.map(x => ({ json: { aktion: 'holen', bereich: 'ally', pfad: r.ordner + '/' + x.pfad, rel: x.pfad } }));

// Alle geholten Dateien in ein Item (Felder f0, f1, …), Dateiname im ZIP = Pfad im Themenordner
const A = $('Holen-Aufträge').all();
const binary = {}; const fehlt = [];
$input.all().forEach((it, i) => { const b = it.binary && it.binary.datei; if (it.json && it.json.ok === true && b) binary['f' + i] = { ...b, fileName: (A[i] && A[i].json.rel) || b.fileName }; else fehlt.push((A[i] && A[i].json.rel) || ('Datei ' + (i + 1))); });
const r = $('Download prüfen').first().json.r || {};
const slug = String(r.titel || 'beitrag').toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'beitrag';
if (!Object.keys(binary).length) return [{ json: { leer: true, fehler: 'Die Dateien konnten nicht geholt werden.' } }];
return [{ json: { felder: Object.keys(binary).join(','), name: 'thema-' + r.thema + '_' + slug + '.zip', fehlt }, binary }];

// Termine für die Maske Kalender aufbereiten (Google Calendar, Berliner Zeit)
const it = $input.all();
const e0 = it[0] && it[0].json && it[0].json.error;
if (e0) return [{ json: { kalender: { ok: false, fehler: String(e0.message || e0).slice(0, 300) } } }];
const z = v => { if (!v) return null; if (v.date) return { tag: v.date, ganz: true }; const d = DateTime.fromISO(v.dateTime || '').setZone('Europe/Berlin'); return d.isValid ? { iso: d.toFormat("yyyy-LL-dd'T'HH:mm"), tag: d.toISODate(), zeit: d.toFormat('HH:mm') } : null; };
// Notiz: Text zum Anzeigen; Notizen mit Formatierung (z. B. von Reclaim) oder über 2000 Zeichen werden im Formular nicht angeboten und bleiben beim Ändern unverändert
const notiz = v => { const roh = String(v || ''); const fest = /<[a-z][^>]*>/i.test(roh) || roh.length > 2000;
  return { beschreibung: fest ? '' : roh, notiz_fest: fest, notiz: roh.replace(/<br\s*\/?>|<\/?(p|div|li)\b[^>]*>/gi, '\n').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\n{3,}/g, '\n\n').trim().slice(0, 1500) }; };
const termine = it.map(x => x.json || {}).filter(j => j.id).map(j => { const a = z(j.start) || {}, e = z(j.end) || {};
  return { id: j.id, titel: j.summary || '(ohne Titel)', ganz: !!a.ganz, start: a.iso || a.tag, ende: e.iso || e.tag, tag: a.tag, von: a.zeit || '', bis: e.zeit || '',
    ende_tag: a.ganz && e.tag ? DateTime.fromISO(e.tag).minus({ days: 1 }).toISODate() : e.tag, ort: j.location || '', ...notiz(j.description), link: j.htmlLink || j.hangoutLink || '' }; });
return [{ json: { kalender: { ok: true, termine } } }];

// Themenordner auflisten (erste Ebene)
const o = $('Download prüfen').isExecuted ? ($('Download prüfen').first().json.r || {}).ordner : (($json.auftrag || {}).ordner);
return [{ json: { aktion: 'liste', bereich: 'ally', pfad: String(o || '') } }];

// Unterordner des Themenordners auflisten (zweite Ebene). Ohne Unterordner noch einmal die erste Ebene, damit der Ablauf weiterläuft.
const w = $input.first().json || {};
const unter = (w.eintraege || []).filter(e => e.ordner && !String(e.name).startsWith('.'));
return (unter.length ? unter : [null]).map(e => ({ json: { aktion: 'liste', bereich: 'ally', pfad: e ? w.pfad + '/' + e.name : w.pfad } }));

// Alle Dateien des Themenordners (erste und zweite Ebene) mit Pfad relativ zum Themenordner
const w = $('Themenordner lesen').first().json || {};
const basis = String(w.pfad || '');
const liste = [];
if (w.ok === true) for (const e of w.eintraege || []) if (!e.ordner && !String(e.name).startsWith('.')) liste.push({ pfad: e.name, ordner: '', name: e.name, bytes: e.bytes });
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.ok !== true || j.pfad === basis) continue;
  const unter = String(j.pfad).slice(basis.length + 1);
  for (const e of j.eintraege || []) if (!e.ordner && !String(e.name).startsWith('.')) liste.push({ pfad: unter + '/' + e.name, ordner: unter, name: e.name, bytes: e.bytes });
}
liste.sort((a, b) => (a.ordner || '').localeCompare(b.ordner || '') || a.name.localeCompare(b.name, 'de', { numeric: true }));
const fehler = w.ok === true ? '' : (w.fehler || 'Der Themenordner konnte nicht gelesen werden.');
return [{ json: { dateien: { ok: !fehler, fehler, liste: liste.slice(0, 300) } } }];
